  Network(List<Segment> segments,List<Cutoff> cutoffs){this(segments,cutoffs,1,List.of());}
  Network options(double density,List<SideBranch> branches){return new Network(segments,cutoffs,density,branches);}
  Network(List<Segment> segments,List<Cutoff> cutoffs,double density,List<SideBranch> branches){splitDensity=density;sideBranches=List.copyOf(branches);this.segments=List.copyOf(segments);this.cutoffs=List.copyOf(cutoffs);var bars=new ArrayList<SedimentIsland>();for(var s:segments){double dx=s.b.x-s.a.x,dz=s.b.z-s.a.z,len=Math.max(.001,Math.hypot(dx,dz)),gradient=Math.abs(s.b.water-s.a.water)/len;if(s.maturity<(density>1?.4:.55)||s.a.radius<Math.max(3.5,4.2/Math.sqrt(density))||gradient>.025||s.a.water<=LargeWorldBuilder.SEA+1)continue;boolean near=false;for(var bar:bars)if(Math.hypot(s.a.x-bar.x,s.a.z-bar.z)<420/density)near=true;if(!near)bars.add(new SedimentIsland(s.a.x,s.a.z,Math.min(density>1?16:24,s.a.radius*(density>1?3:4)),Math.min(density>1?1.2:2,s.a.radius*(density>1?.22:.32)),Math.atan2(dz,dx)));}islands=List.copyOf(bars);}
