  Network append(List<Point> raw,double depth,long seed){return append(raw,depth,seed,null,0,1,0);}
  Network append(List<Point> raw,double depth,long seed,float[] terrain,int n,double block,double follow){return append(raw,depth,seed,terrain,n,block,follow,false);}
