 static List<Point> cutoff(List<Point> points,List<Cutoff> abandoned,float[] terrain,int n,double block){if(terrain==null)return points;for(int i=0;i<points.size()-80;i++){var a=points.get(i);if(a.water>LargeWorldBuilder.SEA+70)continue;double arc=0;for(int j=i+1;j<points.size()&&arc<600;j++){var prev=points.get(j-1);var b=points.get(j);arc+=Math.hypot(b.x-prev.x,b.z-prev.z);if(arc<180||Math.abs(a.water-b.water)>1||Math.hypot(a.x-b.x,a.z-b.z)>Math.max(12,a.radius*2.5))continue;boolean safe=true;for(int k=0;k<=12;k++){var p=lerp(a,b,k/12.);double h=RiverShape.height(terrain,n,p.x/block,p.z/block);if(h<a.water+.5||h>a.water+3.5)safe=false;}if(!safe)continue;abandoned.add(new Cutoff(List.copyOf(points.subList(i,j+1)),2));var shortened=new ArrayList<Point>();shortened.addAll(points.subList(0,i+1));shortened.addAll(points.subList(j,points.size()));return shortened;}}return points;}
 static long key(int x,int z){return ((long)x<<32)|(z&0xffffffffL);}
 static Point lerp(Point a,Point b,double t){return new Point(a.x+(b.x-a.x)*t,a.z+(b.z-a.z)*t,a.radius+(b.radius-a.radius)*t,a.water+(b.water-a.water)*t,flowLerp(a.discharge,b.discharge,t));}
 static double flowLerp(double a,double b,double t){return Double.isFinite(a)&&Double.isFinite(b)?a+(b-a)*t:Double.isFinite(a)?a:b;}
