 static List<Point> smooth(List<Point> raw,long seed){return smooth(raw,seed,null,0,1,0);}
 static List<Point> smooth(List<Point> raw,long seed,float[] terrain,int n,double block,double follow){return smooth(raw,seed,terrain,n,block,follow,false);}
