 static double derivative(double a,double b,double c,double d,double t){return .5*((-a+c)+2*(2*a-5*b+4*c-d)*t+3*(-a+3*b-3*c+d)*t*t);}

 static double surfaceAt(EnvironmentMap global,Point p,int sea){int x=(int)Math.round(p.x),z=(int)Math.round(p.z);if(x<0||z<0||x>=16384||z>=16384)return p.water;float sampled=LargeWorldBuilder.sampleWater(global,x,z);if(sampled>sea)return sampled;int cx=Math.min(2047,x/8),cz=Math.min(2047,z/8);double best=Double.POSITIVE_INFINITY,level=p.water;for(int dz=-1;dz<=1;dz++)for(int dx=-1;dx<=1;dx++){int xx=cx+dx,zz=cz+dz;if(xx<0||zz<0||xx>=2048||zz>=2048)continue;int i=zz*2048+xx;double d=Math.hypot(xx*8-p.x,zz*8-p.z);if(d<best&&EnvironmentMap.at(global.river,i,0)>.1&&global.waterY(i,sea)>Math.round(global.height[i])){best=d;level=global.waterY(i,sea);}}return level;}
